return ['domain'=>'acfml','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'nl_NL','project-id-version'=>'Advanced Custom Fields Multilingual 5.2.0','pot-creation-date'=>'2026-10-20 11:36+0000','po-revision-date'=>'2026-10-20 11:36+0000','x-generator'=>'PTC (Private Translation Cloud)','messages'=>['Advanced Custom Fields Multilingual'=>'Advanced Custom Fields Multilingual','https://wpml.org/documentation/wpml-core-and-add-on-plugins/acfml/'=>'https://wpml.org/documentation/wpml-core-and-add-on-plugins/acfml/','Adds compatibility between WPML and Advanced Custom Fields | <a href="https://wpml.org/documentation/translating-your-contents/acf/?utm_source=plugin&utm_medium=gui&utm_campaign=acfml">Documentation</a>'=>'Voegt compatibiliteit toe tussen WPML en Advanced Custom Fields | <a href="https://wpml.org/documentation/translating-your-contents/acf/?utm_source=plugin&utm_medium=gui&utm_campaign=acfml">Documentatie</a>','OnTheGoSystems'=>'OnTheGoSystems','http://www.onthegosystems.com/'=>'http://www.onthegosystems.com/','Displayed when editing an ACF field in a translation, showing its value in the original language; %1$s and %2$s turn the string into bold, and %3$s is the actual original value.%1$sOriginal%2$s: %3$s'=>'%1$sOrigineel%2$s: %3$s','This type of ACF field will always be set to "Copy once".'=>'Dit type ACF-veld wordt altijd ingesteld op “Eenmalig kopiëren”.','ACF field name:'=>'ACF-veldnaam:','ACF field type:'=>'ACF-veldtype:','Translation preferences'=>'Vertaalvoorkeuren','What to do with field\'s value when post/page is going to be translated'=>'Wat te doen met de waarde van het veld wanneer het bericht/de pagina vertaald gaat worden','Translate (your current setting, no longer offered for this field type)'=>'Vertalen (uw huidige instelling, niet langer beschikbaar voor dit veldtype)','Kept because it is your current setting. This value is no longer offered for this field type.'=>'Behouden omdat dit uw huidige instelling is. Deze waarde wordt niet langer aangeboden voor dit veldtype.','Not recommended for this field type.'=>'Niet aanbevolen voor dit veldtype.','Translated pages start without this content.'=>'Vertaalde pagina\'s beginnen zonder deze inhoud.','Editable in other languages, and starts empty.'=>'Bewerkbaar in andere talen en begint leeg.','Visitors in every language always see exactly what the original shows.'=>'Bezoekers in elke taal zien altijd precies wat het origineel toont.','Shown locked in other languages, so it cannot be edited there.'=>'Wordt vergrendeld getoond in andere talen, dus het kan daar niet worden bewerkt.','Starts the same as the original, then each language goes its own way.'=>'Begint hetzelfde als het origineel, daarna gaat elke taal zijn eigen weg.','Editable in every language, and permanently yours to maintain by hand.'=>'Bewerkbaar in elke taal en permanent door u handmatig te onderhouden.','Visitors see this in their own language.'=>'Bezoekers zien dit in hun eigen taal.','Filled by the translation and edited in the translation editor.'=>'Ingevuld door de vertaling en bewerkt in de vertaal-editor.','Edit the field to set the translation preference.'=>'Bewerk het veld om de vertaalvoorkeur in te stellen.','ACFML is updating translation preferences for strings in Gutenberg Blocks. Keep using your site as usual. This notice will disappear when the process is done.'=>'ACFML is de vertaalvoorkeuren voor strings in Gutenberg-blokken aan het bijwerken. U kunt uw site gewoon blijven gebruiken. Deze melding verdwijnt zodra het proces is voltooid.','ACFML is enabled but not effective. It requires WPML in order to work.'=>'ACFML is ingeschakeld maar werkt niet. Het vereist WPML om te kunnen werken.','ACFML is enabled but not effective. It requires Advanced Custom Fields or ACF PRO in order to work.'=>'ACFML is ingeschakeld maar werkt niet. Advanced Custom Fields of ACF PRO is vereist om te functioneren.','Activate Advanced Custom Fields'=>'Activeer Advanced Custom Fields','Install Advanced Custom Fields'=>'Installeer Advanced Custom Fields','Field groups are set to "Translatable" in WPML settings, which prevents ACF fields from being translated.'=>'Veldgroepen zijn ingesteld op “Vertaalbaar” in de WPML-instellingen, wat voorkomt dat ACF-velden worden vertaald.','This is almost never intended.'=>'Dit is bijna nooit de bedoeling.','A configuration file (wpml-config.xml) controls this setting on this site, so it cannot be changed from here. Edit that file, or ask whoever maintains it to set the ACF field group post type to Not translatable.'=>'Een configuratiebestand (wpml-config.xml) beheert deze instelling op deze site, dus het kan hier niet worden gewijzigd. Bewerk dat bestand of vraag degene die het beheert om het berichttype voor de ACF-veldgroep op “Niet vertaalbaar” in te stellen.','Field group copies already created in other languages stay on the site. Changing this setting does not delete them.'=>'Kopieën van veldgroepen die al in andere talen zijn gemaakt, blijven op de site staan. Het wijzigen van deze instelling verwijdert ze niet.','Set field groups to Not translatable'=>'Stel veldgroepen in op Niet vertaalbaar','Why this matters'=>'Waarom dit belangrijk is','If any field is set to "Translatable", WPML will re-translate the %d posts using this field group.'=>'Als een veld is ingesteld op “Vertalen”, zal WPML de %d berichten die deze veldgroep gebruiken opnieuw vertalen.','Some posts using this field group have translations. Once you change the translation option, WPML needs to update the translation status of the posts. This can take up to 1 minute.'=>'Sommige berichten die deze veldgroep gebruiken hebben vertalingen. Zodra u de vertaaloptie wijzigt, moet WPML de vertaalstatus van de berichten bijwerken. Dit kan tot 1 minuut duren.','Some posts using this field group have translations. Once you change the translation option, WPML needs to update the translation status of the posts. This can take up to %d hours.'=>'Sommige berichten die deze veldgroep gebruiken hebben vertalingen. Zodra u de vertaaloptie wijzigt, moet WPML de vertaalstatus van de berichten bijwerken. Dit kan tot %d uur duren.','Some posts using this field group have translations. Once you change the translation option, WPML needs to update the translation status of the posts. This can take up to %d minutes.'=>'Sommige berichten die deze veldgroep gebruiken hebben vertalingen. Zodra u de vertaaloptie wijzigt, moet WPML de vertaalstatus van de berichten bijwerken. Dit kan tot %d minuten duren.','Locked by WPML so that ACF fields stay translatable. Click here to unlock and change it anyway.'=>'Vergrendeld door WPML zodat ACF-velden vertaalbaar blijven. Klik hier om te ontgrendelen en het toch te wijzigen.','Set translation preferences for the attached taxonomy'=>'Stel vertaalvoorkeuren in voor de gekoppelde taxonomie','Set translation preferences for the attached post type'=>'Stel vertaalvoorkeuren in voor het gekoppelde berichttype','If you want to translate your fields, go to the WPML Settings page and make the taxonomy attached to this field group translatable. '=>'Als u uw velden wilt vertalen, ga dan naar de WPML-instellingenpagina en maak de taxonomie die aan deze veldgroep is gekoppeld vertaalbaar. ','If you want to translate your fields, go to the WPML Settings page and %1$smake the post type attached to this field group translatable%2$s.'=>'Als u uw velden wilt vertalen, ga dan naar de WPML-instellingenpagina en %1$smaak het berichttype dat aan deze veldgroep is gekoppeld vertaalbaar%2$s.','Expert'=>'Expert','Same content in every language, translated'=>'Dezelfde inhoud in elke taal, vertaald','Each language has its own content'=>'Elke taal heeft zijn eigen inhoud','Translate is not offered on container fields, because it replaces the value your theme reads. The fields inside carry their own preferences.'=>'Vertalen wordt niet aangeboden voor containervelden, omdat het de waarde vervangt die uw thema leest. De velden binnenin hebben hun eigen voorkeuren.','Translate lets each language point at its own address, which an external link often needs. A link to a page on this site already points at that page in the reader\'s language, so leave it as it is.'=>'“Vertalen” zorgt ervoor dat elke taal naar zijn eigen adres verwijst, wat vaak nodig is voor een externe link. Een link naar een pagina op deze site verwijst al naar die pagina in de taal van de lezer, dus laat deze ongewijzigd.','Translate sends the link text and the URL. The target keeps the value you set, and a URL you leave as it is points at the page in the reader\'s language.'=>'“Vertalen” verzendt de linktekst en de URL. Het doel behoudt de waarde die u hebt ingesteld, en een URL die u ongewijzigd laat, verwijst naar de pagina in de taal van de lezer.','Translating an address produces one that does not exist. An e-mail address is the same in every language.'=>'Het vertalen van een adres produceert een adres dat niet bestaat. Een e-mailadres is in elke taal hetzelfde.','A color code is not language content. Translating it changes the color your visitors see.'=>'Een kleurcode is geen taalinhoud. Het vertalen ervan verandert de kleur die uw bezoekers zien.','The stored value is a fixed date format that your theme reads. Translating it breaks the format.'=>'De opgeslagen waarde is een vaste datumnotatie die uw thema leest. Het vertalen ervan verbreekt de notatie.','The stored value is the choice key, not the label your visitors see. Translating it stops the key from matching your choices. Translate the labels in <b>String Translation</b> instead.'=>'De opgeslagen waarde is de keuzesleutel, niet het label dat uw bezoekers zien. Het vertalen ervan zorgt ervoor dat de sleutel niet meer overeenkomt met uw keuzes. Vertaal in plaats daarvan de labels in <b>Stringvertaling</b>.','This value is read by your theme or plugin code. A translated value can stop matching what the code expects.'=>'Deze waarde wordt gelezen door uw thema- of plugincode. Een vertaalde waarde kan stoppen met overeenkomen met wat de code verwacht.','The file decides this again on every import, so changes made elsewhere do not stick.'=>'Het bestand beslist dit opnieuw bij elke import, dus wijzigingen die elders zijn gemaakt, blijven niet behouden.','Edit %s, or remove the entry there, to manage this field on this screen.'=>'Bewerk %s, of verwijder het item daar, om dit veld op dit scherm te beheren.','Edit the configuration file, or remove the entry there, to manage this field on this screen.'=>'Bewerk het configuratiebestand, of verwijder het item daar, om dit veld op dit scherm te beheren.','That is not the value selected above. Saving this field group applies the value above.'=>'Dat is niet de hierboven geselecteerde waarde. Het opslaan van deze veldgroep past de bovenstaande waarde toe.','This field group is also in %s. That file re-applies these settings the next time the group is synced.'=>'Deze veldgroep bevindt zich ook in %s. Dat bestand past deze instellingen opnieuw toe de volgende keer dat de groep wordt gesynchroniseerd.','Locked. Managed by your theme, in its wpml-config.xml file.'=>'Vergrendeld. Beheerd door uw thema, in het wpml-config.xml-bestand.','Locked. Managed by a plugin, in its wpml-config.xml file.'=>'Vergrendeld. Beheerd door een plugin, in het wpml-config.xml-bestand.','Locked. Managed by a configuration file WPML downloaded for one of your plugins or themes.'=>'Vergrendeld. Beheerd door een configuratiebestand dat WPML heeft gedownload voor een van uw plugins of thema\'s.','Locked. Managed by the custom XML configuration saved in WPML settings.'=>'Vergrendeld. Beheerd door de aangepaste XML-configuratie die is opgeslagen in de WPML-instellingen.','Locked. Managed by a configuration file on this site.'=>'Vergrendeld. Beheerd door een configuratiebestand op deze site.','Set in the field group "%s", which uses the same field name.'=>'Ingesteld in de veldgroep “%s”, die dezelfde veldnaam gebruikt.','Set in the field group\'s local JSON file.'=>'Ingesteld in het lokale JSON-bestand van de veldgroep.','Set in the field group\'s local JSON file, %s.'=>'Ingesteld in het lokale JSON-bestand van de veldgroep, %s.','Registered with PHP by your theme or a plugin.'=>'Geregistreerd met PHP door uw thema of een plugin.','Set on the WPML Settings screen (Custom Fields Translation).'=>'Ingesteld op het WPML-instellingenscherm (Vertaling aangepaste velden).','Set here, on this screen.'=>'Hier ingesteld, op dit scherm.','Right now this field is translated, so visitors see it in their own language.'=>'Op dit moment is dit veld vertaald, dus bezoekers zien het in hun eigen taal.','Right now this field stays identical in every language.'=>'Op dit moment blijft dit veld identiek in elke taal.','Right now this field starts as a copy in every language, then each language keeps its own.'=>'Op dit moment begint dit veld als een kopie in elke taal, waarna elke taal zijn eigen waarde behoudt.','Right now this field stays out of translations.'=>'Op dit moment blijft dit veld buiten de vertalingen.','Don\'t translate'=>'Niet vertalen','Copy'=>'Kopiëren','Copy once'=>'Eenmalig kopiëren','Translate'=>'Vertalen','Field groups'=>'Veldgroepen','Fields'=>'Velden','Posts'=>'Berichten','Review them one by one'=>'Bekijk ze één voor één','Apply the recommended setup to %d group'=>'Pas de aanbevolen configuratie toe op %d groep' . "\0" . 'Pas de aanbevolen configuratie toe op alle %d','%d ACF field group is not configured for translation.'=>'%d ACF-veldgroep is niet geconfigureerd voor vertaling.' . "\0" . '%d ACF-veldgroepen zijn niet geconfigureerd voor vertaling.','%d post'=>'%d bericht' . "\0" . '%d berichten','%1$s field, used on %2$s, would be skipped and stay in %3$s.'=>'%1$s veld, gebruikt op %2$s, wordt overgeslagen en blijft in het %3$s.' . "\0" . '%1$s velden, gebruikt op %2$s, worden overgeslagen en blijven in het %3$s.','%1$s field, used on %2$s, would be skipped and stay untranslated.'=>'%1$s veld, gebruikt op %2$s, wordt overgeslagen en blijft onvertaald.' . "\0" . '%1$s velden, gebruikt op %2$s, worden overgeslagen en blijven onvertaald.','You are not allowed to change the translation setup of ACF field groups.'=>'U heeft geen toestemming om de vertaalconfiguratie van ACF-veldgroepen te wijzigen.','You are not allowed to change the WPML translation settings on this site.'=>'U heeft geen toestemming om de WPML-vertaalinstellingen op deze site te wijzigen.','To change the translation options for custom fields, edit the field group "%s".'=>'Om de vertaalopties voor aangepaste velden te wijzigen, bewerkt u de veldgroep “%s”.','These fields come from ACF’s Local JSON files. To change their translation options, go to ACF → Field Groups, sync them, and then edit their settings.'=>'Deze velden zijn afkomstig uit de lokale JSON-bestanden van ACF. Om hun vertaalopties te wijzigen, gaat u naar ACF → Veldgroepen, synchroniseert u ze en bewerkt u vervolgens hun instellingen.','This field and its translation setting are registered via PHP by your theme or plugin. Changes made here will override the original configuration.'=>'Dit veld en de bijbehorende vertaalinstelling zijn via PHP geregistreerd door uw thema of plugin. Wijzigingen die hier worden aangebracht, zullen de oorspronkelijke configuratie overschrijven.','ACF translation setup'=>'ACF-vertaalconfiguratie','Translation setup'=>'Vertaalconfiguratie','You are not allowed to review the translation setup of ACF field groups.'=>'U heeft geen toestemming om de vertaalconfiguratie van ACF-veldgroepen te bekijken.','Field group'=>'Veldgroep','Setup'=>'Configuratie','Actions'=>'Acties','This site has no ACF field groups yet.'=>'Deze site heeft nog geen ACF-veldgroepen.','Alert:'=>'Waarschuwing:','How to do that'=>'Hoe u dat doet','View fields'=>'Velden bekijken','Open Dashboard'=>'Dashboard openen','Apply the recommended setup'=>'Pas de aanbevolen configuratie toe','Every field group stored in this site’s database already has a translation setup.'=>'Elke veldgroep die in de database van deze site is opgeslagen, heeft al een vertaalconfiguratie.','Back to the field groups'=>'Terug naar de veldgroepen','Every field in those groups then gets the translation preference WPML recommends for its field type. A preference that was set by hand in one of them is replaced.'=>'Elk veld in die groepen krijgt dan de vertaalvoorkeur die WPML aanbeveelt voor dat veldtype. Een voorkeur die handmatig was ingesteld in een van hen, wordt vervangen.','Field groups that come from your theme, a plugin’s code, or an acf-json file are not changed. They cannot be saved from here.'=>'Veldgroepen die afkomstig zijn van uw thema, de code van een plugin of een acf-json-bestand worden niet gewijzigd. Ze kunnen niet vanaf hier worden opgeslagen.','Cancel'=>'Annuleren','%d field group.'=>'%d veldgroep.' . "\0" . '%d veldgroepen.','All of them have a translation setup.'=>'Ze hebben allemaal een vertaalconfiguratie.','%d is not configured.'=>'%d is niet geconfigureerd.' . "\0" . '%d zijn niet geconfigureerd.','Apply recommended setup to the %d unconfigured group'=>'Pas aanbevolen configuratie toe op de %d niet-geconfigureerde groep' . "\0" . 'Pas aanbevolen configuratie toe op alle %d niet-geconfigureerde groepen','This sets %1$d field group to “%2$s”.'=>'Dit stelt %1$d veldgroep in op “%2$s”.' . "\0" . 'Dit stelt %1$d veldgroepen in op “%2$s”.','%d field group is defined in code, so it cannot be configured from here.'=>'%d veldgroep is gedefinieerd in code en kan hier niet worden geconfigureerd.' . "\0" . '%d veldgroepen zijn gedefinieerd in code en kunnen hier niet worden geconfigureerd.','Not configured'=>'Niet geconfigureerd','Not configured (defined in code)'=>'Niet geconfigureerd (gedefinieerd in code)','Set for each field (defined in code)'=>'Ingesteld voor elk veld (gedefinieerd in code)','Set for each field in WPML Settings (defined in code)'=>'Ingesteld per veld in WPML-instellingen (gedefinieerd in code)','%d field set manually'=>'%d veld handmatig ingesteld' . "\0" . '%d velden handmatig ingesteld','Nothing decides how these fields are translated. Set %s on the fields in the code that registers this group.'=>'Niets bepaalt hoe deze velden worden vertaald. Stel %s in op de velden in de code die deze groep registreert.','from an acf-json file'=>'vanuit een acf-json-bestand','from an acf-json file that is newer than this site’s copy'=>'vanuit een acf-json-bestand dat nieuwer is dan de kopie van deze site','from your theme or a plugin’s code'=>'vanuit uw thema of de code van een plugin','%d field group now uses the recommended setup.'=>'%d veldgroep gebruikt nu de aanbevolen configuratie.' . "\0" . '%d veldgroepen gebruiken nu de aanbevolen configuratie.','%d field group has a newer acf-json file waiting to be synced, so that file decides its setup.'=>'%d veldgroep heeft een nieuwer acf-json-bestand dat wacht om te worden gesynchroniseerd; dat bestand bepaalt de configuratie.' . "\0" . '%d veldgroepen hebben een nieuwer acf-json-bestand dat wacht om te worden gesynchroniseerd; die bestanden bepalen hun configuratie.','Translation Option'=>'Vertaaloptie','Multilingual Setup'=>'Meertalige configuratie','Loading...'=>'Laden...','Activate <b>String Translation</b>'=>'Activeer <b>stringvertaling</b>','To translate field group names and labels, please %1$sinstall and activate WPML’s String Translation add-on%2$s.'=>'Om veldgroepnamen en labels te vertalen, moet u de add-on %1$sWPML String Translation installeren en activeren%2$s.','Activate now'=>'Nu activeren','Go back'=>'Ga terug','Set Up <b>Field Group Translation</b>'=>'Stel <b>veldgroepvertaling</b> in','To translate field labels from the <b>Translation Management</b> dashboard, finish the <b>Multilingual Setup</b> and save your field group settings.'=>'Om veldlabels te vertalen vanuit het <b>Vertaalbeheer</b>-dashboard, voltooit u de <b>Meertalige configuratie</b> en slaat u de instellingen van uw veldgroep op.','OK'=>'OK','Translate Field Labels'=>'Vertaal veldlabels','To translate field labels, use the <b>Translation Management</b> dashboard.'=>'Gebruik het <b>Vertaalbeheer</b>-dashboard om veldlabels te vertalen.','Translate in <b>Translation Management</b>'=>'Vertalen in <b>vertaalbeheer</b>','Don’t want to translate field labels? %1$sLearn how to disable field label translation%2$s'=>'Wilt u veldlabels niet vertalen? %1$sLeer hoe u de vertaling van veldlabels uitschakelt%2$s','Field Labels Partly Translated'=>'Veldlabels gedeeltelijk vertaald','Some field labels in this group are still untranslated. To finish translating them, go to the <b>Translation Management</b> dashboard.'=>'Sommige veldlabels in deze groep zijn nog onvertaald. Ga naar het <b>Vertaalbeheer</b>-dashboard om ze af te ronden.','Fields Labels Already Translated'=>'Veldlabels al vertaald','You already translated all field labels in this group. To update any translations, go to the <b>Translation Management</b> dashboard.'=>'U heeft alle veldlabels in deze groep al vertaald. Ga naar het <b>Vertaalbeheer</b>-dashboard om vertalingen bij te werken.','Go to <b>Translation Management</b>'=>'Ga naar <b>vertaalbeheer</b>','Select a translation option for this field group'=>'Selecteer een vertaaloptie voor deze veldgroep','Visitors everywhere see the same pages, in their own language. Text is translated; layout and settings stay identical.'=>'Bezoekers zien overal dezelfde pagina\'s, in hun eigen taal. Tekst wordt vertaald; lay-out en instellingen blijven identiek.','You translate in the WPML <b>Translation Editor</b>. This works with automatic translation and <b>Translate Everything</b>.'=>'U vertaalt in de WPML <b>Vertaal-editor</b>. Dit werkt met automatische vertaling en <b>Vertaal alles</b>.','Every language’s pages are written and maintained on their own. Fields start as a copy of the original, then go their own way.'=>'De pagina\'s van elke taal worden afzonderlijk geschreven en onderhouden. Velden beginnen als een kopie van het origineel en gaan daarna hun eigen weg.','You edit each language in the WordPress editor. WPML does not sync them afterwards, and automatic translation does not apply.'=>'U bewerkt elke taal in de WordPress-editor. WPML synchroniseert ze daarna niet meer en automatische vertaling is niet van toepassing.','If you are migrating a site, your existing field groups will use the Expert setup. This allows you to manually choose the translation option for each field in the group.'=>'Als u een site migreert, gebruiken uw bestaande veldgroepen de Expert-configuratie. Hiermee kunt u handmatig de vertaaloptie voor elk veld in de groep kiezen.','This option is %1$snot recommended%2$s for new field groups.'=>'Deze optie wordt %1$sniet aanbevolen%2$s voor nieuwe veldgroepen.','Expert setup documentation'=>'Documentatie over Expert-configuratie','Choose'=>'Kiezen','recommended for this site'=>'aanbevolen voor deze site','Change option'=>'Optie wijzigen','A Much Simpler Way to Translate Your ACF Sites'=>'Een veel eenvoudigere manier om uw ACF-sites te vertalen','This new release of ACFML allows you to configure multilingual sites in one-click, instead of many complex settings. Choose how to setup the translation for the fields.'=>'Met deze nieuwe versie van ACFML kunt u meertalige sites met één klik configureren, in plaats van met veel complexe instellingen. Kies hoe u de vertaling voor de velden wilt instellen.','Go to WPML Settings'=>'Ga naar WPML-instellingen','Need help choosing?'=>'Hulp nodig bij het kiezen?','Documentation'=>'Documentatie','How to translate field labels »'=>'Hoe veldlabels te vertalen »','This setup translates field values.'=>'Deze configuratie vertaalt veldwaarden.','Translate field labels and dropdown choice labels separately. Find them under ACF Field Group in the <b>Translation Dashboard</b>.'=>'Vertaal veldlabels en labels van dropdown-keuzes apart. U vindt ze onder ACF Field Group in het <b>Translation Dashboard</b>.','Review these translation setting changes'=>'Controleer deze wijzigingen in de vertaalinstellingen','Saving this field group makes these changes:'=>'Het opslaan van deze veldgroep brengt deze wijzigingen aan:','%1$s: from “%2$s” to “%3$s”'=>'%1$s: van “%2$s” naar “%3$s”','Switching to the field-by-field setup keeps every field\'s current setting. From here you set each field yourself.'=>'Bij het overschakelen naar de veld-voor-veld configuratie blijven de huidige instellingen van elk veld behouden. Vanaf hier stelt u elk veld zelf in.','New translations use the new settings automatically.'=>'Nieuwe vertalingen gebruiken automatisch de nieuwe instellingen.','Not set'=>'Niet ingesteld','No posts with translations use this field group yet, so nothing has to be sent again.'=>'Er zijn nog geen berichten met vertalingen die deze veldgroep gebruiken, dus er hoeft niets opnieuw te worden verzonden.','No terms with translations use this field group yet, so nothing has to be sent again.'=>'Er zijn nog geen termen met vertalingen die deze veldgroep gebruiken, dus er hoeft niets opnieuw te worden verzonden.','No posts or terms with translations use this field group yet, so nothing has to be sent again.'=>'Er zijn nog geen berichten of termen met vertalingen die deze veldgroep gebruiken, dus er hoeft niets opnieuw te worden verzonden.','Only apply to new translations'=>'Alleen toepassen op nieuwe vertalingen','Checking how much content this affects...'=>'Controleren op hoeveel inhoud dit invloed heeft...','Save changes'=>'Wijzigingen opslaan','No, go back'=>'Nee, ga terug','Updating them sends them for translation again, which may use translation words.'=>'Door ze bij te werken, worden ze opnieuw ter vertaling verzonden, waarvoor vertaalwoorden kunnen worden gebruikt.','Updating them marks their translations as needing an update. WPML does not send them for translation. You can send them from the Translation Dashboard.'=>'Als u ze bijwerkt, worden hun vertalingen gemarkeerd als \'moet worden bijgewerkt\'. WPML verzendt ze niet voor vertaling. U kunt ze verzenden vanuit het Translation Dashboard.','Switching the setup applies the recommended value to the %d field in this group.'=>'Het wijzigen van de configuratie past de aanbevolen waarde toe op het %d veld in deze groep.' . "\0" . 'Het wijzigen van de configuratie past de aanbevolen waarde toe op alle %d velden in deze groep.','%d post already has translations that used the old settings.'=>'%d bericht heeft al vertalingen die de oude instellingen gebruikten.' . "\0" . '%d berichten hebben al vertalingen die de oude instellingen gebruikten.','%d term already has translations that used the old settings.'=>'%d term heeft al vertalingen die de oude instellingen gebruikten.' . "\0" . '%d termen hebben al vertalingen die de oude instellingen gebruikten.','%d post uses this field group.'=>'%d bericht gebruikt deze veldgroep.' . "\0" . '%d berichten gebruiken deze veldgroep.','%d post is translated by hand, so WPML does not send it for translation.'=>'%d bericht is handmatig vertaald, dus WPML verzendt het niet voor vertaling.' . "\0" . '%d berichten zijn handmatig vertaald, dus WPML verzendt ze niet voor vertaling.','Also update the %d existing post'=>'Werk ook het %d bestaande bericht bij' . "\0" . 'Werk ook de %d bestaande berichten bij','Also update the %d existing term'=>'Werk ook de %d bestaande term bij' . "\0" . 'Werk ook de %d bestaande termen bij','Also update the %1$d existing posts and %2$d terms'=>'Werk ook de %1$d bestaande berichten en %2$d termen bij','Also update the %1$d existing post and %2$d terms'=>'Werk ook het %1$d bestaande bericht en %2$d termen bij','Also update the %1$d existing posts and %2$d term'=>'Werk ook de %1$d bestaande berichten en %2$d term bij','Also update the %1$d existing post and %2$d term'=>'Werk ook het %1$d bestaande bericht en %2$d term bij','This field group is shown on an Options page.'=>'Deze veldgroep wordt getoond op een optiepagina.','That is usually site-wide content like your header, footer, or global blocks.'=>'Dat is meestal sitebrede inhoud zoals uw header, footer of globale blokken.','To translate that content, use the %1$sWPML Translation Dashboard%2$s.'=>'Gebruik het %1$sWPML Vertaalbeheer%2$s om die inhoud te vertalen.','The options below still decide how each field behaves: translated, copied to every language, or kept separately per language.'=>'De onderstaande opties bepalen nog steeds hoe elk veld zich gedraagt: vertaald, gekopieerd naar elke taal, of afzonderlijk per taal bewaard.','This field group also appears on an Options page.'=>'Deze veldgroep verschijnt ook op een optiepagina.','That content is translated in the %1$sWPML Translation Dashboard%2$s, and the option you choose here decides how each of its fields behaves.'=>'Die inhoud wordt vertaald in het %1$sWPML Vertaalbeheer%2$s, en de optie die u hier kiest bepaalt hoe elk van de velden zich gedraagt.','Post Type Translation'=>'Berichttypevertaling','Labels Translation'=>'Labels vertalen','Taxonomy Translation'=>'Taxonomievertaling','Finish the ACF <b>Multilingual Setup</b>'=>'Voltooi de ACF <b>meertalige configuratie</b>','Before you can start translating, you need to edit each ACF Field Group to set a translation option for the fields inside it.'=>'Voordat u kunt beginnen met vertalen, moet u elke ACF-veldgroep bewerken om een vertaaloptie in te stellen voor de velden erin.','Read more about %1$show to translate your ACF custom fields%2$s'=>'Lees meer over %1$shoe u uw aangepaste ACF-velden kunt vertalen%2$s','%1$sSet translation options%2$s'=>'%1$sVertaalopties instellen%2$s','Let\'s Start Translating!'=>'Laten we beginnen met vertalen!','Edit each Field Group to select a translation option for the fields inside it. If you don\'t set a translation option, you will not be able to translate your fields.'=>'Bewerk elke veldgroep om een vertaaloptie te selecteren voor de velden erin. Als u geen vertaaloptie instelt, kunt u uw velden niet vertalen.','A field in "%s" has the same name as a field in another field group. WPML stores translation preferences by field name, so two fields that share a name cannot be set differently.'=>'Een veld in “%s” heeft dezelfde naam als een veld in een andere veldgroep. WPML slaat vertaalvoorkeuren op per veldnaam, dus twee velden die een naam delen kunnen niet verschillend worden ingesteld.','Some fields in "%s" have the same name as fields in other field groups. WPML stores translation preferences by field name, so fields that share a name cannot be set differently.'=>'Sommige velden in “%s” hebben dezelfde naam als velden in andere veldgroepen. WPML slaat vertaalvoorkeuren op per veldnaam, dus velden die een naam delen kunnen niet verschillend worden ingesteld.','What you set here may not be what your visitors get'=>'Wat u hier instelt, is mogelijk niet wat uw bezoekers te zien krijgen','The field %1$s also exists in "%2$s". Rename this field to give it a translation setting of its own.'=>'Het veld %1$s bestaat ook in “%2$s”. Wijzig de naam van dit veld om het een eigen vertaalinstelling te geven.','See both fields'=>'Bekijk beide velden','Go to Media Translation settings'=>'Ga naar de instellingen voor mediavertaling','This content has ACF image, gallery, or file fields, but the alt text, caption, and title of their media will not be sent for translation. To include them, turn on "Translate Media Library texts when translating content" in WPML Media Translation settings.'=>'Deze inhoud heeft ACF-afbeeldings-, galerij- of bestandsvelden, maar de alt-tekst, het bijschrift en de titel van hun media worden niet verzonden voor vertaling. Om ze op te nemen, schakel je “Media Library-teksten vertalen bij het vertalen van content” in bij de instellingen van WPML Media Translation.','Media texts are not being translated'=>'Media-teksten worden niet vertaald','%1$sGo to Media Translation settings%2$s'=>'%1$sGa naar de instellingen voor mediavertaling%2$s','Translate this Options page from the <b>Translation Dashboard</b>'=>'Vertaal deze optiepagina vanuit het <b>Vertaalbeheer</b>','You no longer need to switch the admin language to translate options manually. Translate all your options from the %1$sTranslation Dashboard%2$s.'=>'U hoeft de admin-taal niet langer te wisselen om opties handmatig te vertalen. Vertaal al uw opties vanuit het %1$sVertaalbeheer%2$s.','Go to the Translation Dashboard'=>'Ga naar het vertaalbeheer','To change a finished translation, go to %1$sTranslation Jobs%2$s and click on the Edit Translation icon.'=>'Om een voltooide vertaling te wijzigen, gaat u naar %1$sVertaaltaken%2$s en klikt u op het pictogram Vertaling bewerken.','Go to Translation Jobs'=>'Ga naar vertaaltaken','WPML blocked this save to prevent data loss. The form sent about %1$s fields, but the PHP max_input_vars limit on this server (%2$s) let fewer through. Saving now would permanently delete the fields that did not arrive, including repeater rows. Nothing was saved. Ask your host to raise max_input_vars above %1$s and save again.'=>'WPML heeft deze opslag geblokkeerd om gegevensverlies te voorkomen. Het formulier verzond ongeveer %1$s velden, maar de PHP max_input_vars limiet op deze server liet er slechts (%2$s) door. Nu opslaan zou de velden die niet zijn aangekomen permanent verwijderen, inclusief repeater-rijen. Er is niets opgeslagen. Vraag uw host om max_input_vars te verhogen tot boven %1$s en sla opnieuw op.','Save blocked to prevent data loss'=>'Opslaan geblokkeerd om gegevensverlies te voorkomen','You need to %1$stranslate this post manually%2$s because the field groups attached to it use different translation options:'=>'U moet %1$sdit bericht handmatig vertalen%2$s omdat de veldgroepen die eraan gekoppeld zijn verschillende vertaalopties gebruiken:','and %d more.'=>'en nog %d.','Show all field groups'=>'Toon alle veldgroepen','and %d more'=>'en nog %d','You need to translate this post manually because the field groups attached to it use different translation options: %s.'=>'U moet dit bericht handmatig vertalen omdat de veldgroepen die eraan gekoppeld zijn verschillende vertaalopties gebruiken: %s.','Edit %s'=>'Bewerk %s','Go to documentation'=>'Ga naar documentatie','This field value is copied from the default language and will be kept in sync across languages.'=>'Deze veldwaarde is gekopieerd uit de standaardtaal en zal in alle talen gesynchroniseerd blijven.','Synchronise translations'=>'Vertalingen synchroniseren','Keep repeater and flexible sub-fields in the same order as the default language.'=>'Houd repeater- en flexibele subvelden in dezelfde volgorde als de standaardtaal.','ACFML Synchronise translations'=>'ACFML Vertalingen synchroniseren','Translate ACF Local JSON and PHP-Registered Fields'=>'Vertaal lokale ACF JSON- en via PHP geregistreerde velden','ACF allows you to %1$sregister fields via PHP%2$s or %3$ssave field settings as JSON files%4$s. You can also save post types, taxonomies, or options pages settings to JSON files.'=>'ACF stelt u in staat om %1$svelden te registreren via PHP%2$s of %3$sveldinstellingen op te slaan als JSON-bestanden%4$s. U kunt ook instellingen voor berichttypen, taxonomieën of optiepagina\'s opslaan in JSON-bestanden.','Configure how ACF Multilingual handles translations for these items.'=>'Configureer hoe ACF Multilingual vertalingen voor deze items afhandelt.','Sync <b>Translation Preferences</b> for Local Fields'=>'Synchroniseer <b>vertaalvoorkeuren</b> voor lokale velden','Don’t sync translation preferences'=>'Vertaalvoorkeuren niet synchroniseren','Sync once now'=>'Nu eenmalig synchroniseren','Sync on every request (may affect performance)'=>'Synchroniseer bij elk verzoek (kan prestaties beïnvloeden)','Register Labels for Translation'=>'Labels registreren voor vertaling','Scans post types, taxonomies, options pages, and field groups stored in the "acf-json" directory, then registers their labels with WPML so you can translate them.'=>'Scant berichttypen, taxonomieën, optiepagina\'s en veldgroepen die zijn opgeslagen in de map “acf-json” en registreert vervolgens hun labels bij WPML zodat u ze kunt vertalen.','Don’t register labels'=>'Labels niet registreren','Register labels now'=>'Labels nu registreren','Apply'=>'Toepassen','The synchronization of translation preferences is disabled.'=>'De synchronisatie van vertaalvoorkeuren is uitgeschakeld.','Translation preferences synchronized.'=>'Vertaalvoorkeuren gesynchroniseerd.','The synchronization of translation preferences is enabled.'=>'De synchronisatie van vertaalvoorkeuren is ingeschakeld.','%s group'=>'%s groep' . "\0" . '%s groepen','%s post type'=>'%s berichttype' . "\0" . '%s berichttypen','%s taxonomy'=>'%s taxonomie' . "\0" . '%s taxonomieën','%s options page'=>'%s optiepagina' . "\0" . '%s optiepagina\'s','No local field groups, post types, taxonomies, or Options pages were found.'=>'Er zijn geen lokale veldgroepen, berichttypen, taxonomieën of optiepagina\'s gevonden.','Used between elements of a two elements list and '=>' en ','Used before the last element of a three or more elements list, and '=>', en ','Successfully registered labels for %s.'=>'Labels succesvol geregistreerd voor %s.','%1$sChange translation settings%2$s'=>'%1$sVertaalinstellingen wijzigen%2$s','%1$sTranslate labels%2$s'=>'%1$sLabels vertalen%2$s','Not translatable'=>'Niet vertaalbaar','Translatable'=>'Vertaalbaar','only show translated items'=>'alleen vertaalde items tonen','use translation if available or fallback to default language'=>'gebruik vertaling indien beschikbaar of val terug op de standaardtaal','This content must be translated manually due to the translation option you selected for the "%1$s" field group.'=>'Deze inhoud moet handmatig worden vertaald vanwege de vertaaloptie die u hebt geselecteerd voor de veldgroep “%1$s”.']];